import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  uniform,
  positionLocal,
  abs,
  max,
  min,
  length,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, PointLight, DoubleSide } = THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {};
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#1a1a22' },
    { at: 1, hex: '#111116' },
  ];
  const topHex = gradientStops[0]?.hex ?? '#1a1a22';
  const bottomHex = gradientStops[gradientStops.length - 1]?.hex ?? '#111116';
  const accentHex = colors.accent ?? '#ff2a38';
  const paperHex = colors.paper ?? '#e8ecf2';
  const borderHex = '#26262f';

  const items = config.textContent ?? spec.textContent ?? [];
  const findItem = (role, fallback) =>
    items.find((i) => i.role === role)?.text ?? fallback;

  const quoteMarkText = findItem('quote-mark', '\u201C');
  const quoteText = findItem(
    'quote',
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.'
  );
  const attributionText = findItem('attribution', 'M. OKAFOR');
  const captionText = findItem('caption', 'COLLECTOR SINCE 2019');

  const root = new Group();
  root.name = 'testimonial-panel';

  // ---------------------------------------------------------------
  // Panel dimensions
  // ---------------------------------------------------------------
  const panelW = 3.4;
  const panelH = 1.9;
  const halfW = panelW / 2;
  const halfH = panelH / 2;
  const radius = 0.06;
  const borderWidth = 0.012;

  // ---------------------------------------------------------------
  // Contact / depth shadow behind the panel for surface depth
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(panelW * 1.15, panelH * 1.15);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  {
    const d = uv().sub(vec2(0.5, 0.5)).length();
    const falloff = smoothstep(0.5, 0.15, d).mul(0.5);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = falloff;
  }
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.03, -0.06);
  root.add(shadowMesh);

  // ---------------------------------------------------------------
  // Panel surface — rounded rect via SDF, vertical gradient + hairline
  // ---------------------------------------------------------------
  const panelGeo = new PlaneGeometry(panelW, panelH, 1, 1);
  const panelMat = new MeshPhysicalNodeMaterial({ transparent: true, side: DoubleSide });
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  panelMat.clearcoatRoughness = 0.4;

  const uPanelOpacity = uniform(0.0);

  {
    const p = positionLocal.xy;
    const bx = float(halfW - radius);
    const by = float(halfH - radius);
    const qx = abs(p.x).sub(bx);
    const qy = abs(p.y).sub(by);
    const qxC = max(qx, float(0.0));
    const qyC = max(qy, float(0.0));
    const outside = length(vec2(qxC, qyC));
    const inside = min(max(qx, qy), float(0.0));
    const dist = outside.add(inside).sub(float(radius));

    const alphaMask = smoothstep(float(0.004), float(-0.004), dist);
    const borderMask = smoothstep(float(borderWidth), float(0.0), abs(dist));

    const topColor = color(new Color(topHex));
    const bottomColor = color(new Color(bottomHex));
    const gradientColor = mix(topColor, bottomColor, float(1.0).sub(uv().y));
    const borderColor = color(new Color(borderHex));

    panelMat.colorNode = mix(gradientColor, borderColor, borderMask);
    panelMat.opacityNode = alphaMask.mul(uPanelOpacity);
  }

  const panelMesh = new Mesh(panelGeo, panelMat);
  root.add(panelMesh);

  // ---------------------------------------------------------------
  // Rim / accent light local to this node — catches the mark bowl edge
  // ---------------------------------------------------------------
  const rimLight = new PointLight(new Color(accentHex), 0.9, 4.0, 2.0);
  rimLight.position.set(-1.0, 1.0, 1.2);
  root.add(rimLight);

  // ---------------------------------------------------------------
  // Layout math
  // ---------------------------------------------------------------
  const leftX = -halfW + 0.5;
  const topY = halfH - 0.5;

  // ---------------------------------------------------------------
  // Oversized quotation mark — extruded look via layered glyph
  // ---------------------------------------------------------------
  const markGroup = new Group();
  const markBack = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 62,
    color: '#8a1015',
    align: 'left',
  });
  markBack.position.set(0, 0, -0.04);
  markGroup.add(markBack);

  const markFront = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 62,
    color: accentHex,
    align: 'left',
  });
  markFront.position.set(0, 0, 0.0);
  markGroup.add(markFront);

  markGroup.position.set(leftX, topY - 0.31, 0.02);
  root.add(markGroup);

  // ---------------------------------------------------------------
  // Quote body — floats above the surface for raking-light edge read
  // ---------------------------------------------------------------
  const quoteMesh = ctx.fontAtlas.createText(quoteText, {
    fontSize: 20,
    color: paperHex,
    align: 'left',
    maxWidthPx: 240,
  });
  quoteMesh.position.set(leftX, -0.05, 0.03);
  root.add(quoteMesh);

  // ---------------------------------------------------------------
  // Attribution row — accent rule + mono label
  // ---------------------------------------------------------------
  const ruleGeo = new PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color(new Color(accentHex)).mul(1.4);
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  const attribY = -0.62;
  ruleMesh.position.set(leftX + 0.1, attribY, 0.02);
  root.add(ruleMesh);

  const attributionMesh = ctx.fontAtlas.createText(attributionText, {
    fontSize: 13,
    color: paperHex,
    align: 'left',
    letterSpacingPx: 1.04,
  });
  attributionMesh.position.set(leftX + 0.3, attribY, 0.02);
  root.add(attributionMesh);

  const captionMesh = ctx.fontAtlas.createText(captionText, {
    fontSize: 9,
    color: '#8d8d97',
    align: 'left',
    letterSpacingPx: 1.08,
  });
  captionMesh.position.set(leftX, attribY - 0.22, 0.02);
  root.add(captionMesh);

  // ---------------------------------------------------------------
  // Motion — weighted mount, no idle motion
  // ---------------------------------------------------------------
  root.position.y += 0.2;
  markGroup.scale.setScalar(1.04);

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: root.position.y - 0.2,
    duration: 0.5,
    ease: 'power2.out',
  });
  tl.to(
    uPanelOpacity,
    {
      value: 1,
      duration: 0.5,
      ease: 'power2.out',
    },
    '<'
  );
  tl.to(
    markGroup.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    '-=0.15'
  );

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();

    const disposeObj = (obj) => {
      obj.traverse?.((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            if (m.map) m.map.dispose?.();
            m.dispose?.();
          });
        }
      });
    };

    disposeObj(root);
  };

  return root;
}
